#[verifier::external_trait_specification]
#[verifier::external_trait_extension(NotSpec via NotSpecImpl)]
pub trait ExNot {
    type ExternalTraitSpecificationFor: core::ops::Not;
    type Output;

    spec fn obeys_not_spec() -> bool;
    spec fn not_req(self) -> bool where Self: Sized;
    spec fn not_spec(self) -> Self::Output where Self: Sized;

    fn not(self) -> (ret: Self::Output)
        requires self.not_req(),
        ensures Self::obeys_not_spec() ==> ret == self.not_spec();
}

pub open spec fn range_bounds_contains_start_ensures<T: ?Sized, U: ?Sized>(
    bound: Bound<&T>,
    item: &U,
    result: bool,
) -> bool
where
    T: PartialOrd<U>,
    U: PartialOrd<T>,
{
    match bound {
        Bound::Included(start) => call_ensures(<T as PartialOrd<U>>::le, (start, item), result),
        Bound::Excluded(start) => call_ensures(<T as PartialOrd<U>>::lt, (start, item), result),
        Bound::Unbounded => result,
    }
}

pub open spec fn range_bounds_contains_end_ensures<T: ?Sized, U: ?Sized>(
    bound: Bound<&T>,
    item: &U,
    result: bool,
) -> bool
where
    T: PartialOrd<U>,
    U: PartialOrd<T>,
{
    match bound {
        Bound::Included(end) => call_ensures(<U as PartialOrd<T>>::le, (item, end), result),
        Bound::Excluded(end) => call_ensures(<U as PartialOrd<T>>::lt, (item, end), result),
        Bound::Unbounded => result,
    }
}

#[verifier::external_trait_specification]
#[verifier::external_trait_extension(RangeBoundsSpec via RangeBoundsSpecImpl)]
pub trait ExRangeBounds<T: ?Sized> {
    type ExternalTraitSpecificationFor: RangeBounds<T>;

    spec fn spec_start_bound(&self) -> SpecBound<&T>;
    spec fn spec_end_bound(&self) -> SpecBound<&T>;

    fn start_bound(&self) -> (result: Bound<&T>);
    fn end_bound(&self) -> (result: Bound<&T>);

    fn contains<U>(&self, item: &U) -> (ret: bool)
        where
            T: PartialOrd<U>,
            U: ?Sized + PartialOrd<T>
        default_ensures
            exists|start: Bound<&T>, start_ok: bool| {
                &&& #[trigger] call_ensures(Self::start_bound, (self,), start)
                &&& range_bounds_contains_start_ensures(start, item, start_ok)
                &&& if start_ok {
                    exists|end: Bound<&T>, end_ok: bool| {
                        &&& #[trigger] call_ensures(Self::end_bound, (self,), end)
                        &&& range_bounds_contains_end_ensures(end, item, end_ok)
                        &&& ret == end_ok
                    }
                } else {
                    !ret
                }
            }
    ;
}

